fn excluded(name: &str) -> bool {
    TIMEMAP_EXCLUDED.iter().any(|&(n, _)| n == name)
}

fn scale(name: &str) -> TimeScale {
    TimeScale::parse(name).expect("known time scale")
}

/// The probe's `scale_frame( c, ts, is_to )`.
fn scale_frame(c: usize, ts: &str, is_to: bool) -> TimeFrame {
    let mut f = TimeFrame::new(TimeSystem::Mjd);
    f.set_time_origin(55000.5);
    f.set_timescale(scale(ts));
    if c > 0 {
        let p = cases::PROPS[usize::from(is_to)];
        f.set_obs_lon(p[0]);
        f.set_obs_lat(p[1]);
        f.set_dut1(p[2]);
        f.set_dtai(p[3]);
        f.set_lt_offset(p[4]);
        if is_to && c == 2 {
            f.set_align_timescale(TimeScale::Utc);
        }
        if is_to && c == 3 {
            f.set_align_timescale(TimeScale::Last);
        }
    }
    f
}

/// A Frame of the System grid: the probe sets System, TimeOrigin and Unit
/// in that order on a TT Frame.
fn system_frame(sys: &str) -> TimeFrame {
    let (system, origin, unit) = match sys {
        "MJD" => (TimeSystem::Mjd, 55000.5, "d"),
        "JD" => (TimeSystem::Jd, 2455000.5, "h"),
        "JEPOCH" => (TimeSystem::Jepoch, 2009.25, "yr"),
        "BEPOCH" => (TimeSystem::Bepoch, 2009.5, "yr"),
        other => panic!("unknown system {other}"),
    };
    let mut f = TimeFrame::new(TimeSystem::Mjd);
    f.set_timescale(TimeScale::Tt);
    f.set_system(system);
    f.set_time_origin(origin);
    f.set_unit(1, unit).unwrap();
    f
}

fn convert(from: &TimeFrame, to: &TimeFrame, points: [f64; 2]) -> Result<Option<[f64; 2]>, ()> {
    let Some(fs) = from.convert_to(to, &[]).map_err(|_| ())? else {
        return Ok(None);
    };
    let map = fs.mapping(FrameRef::Base, FrameRef::Current).unwrap();
    let pts = PointSet::from_columns(&[&points[..]]).unwrap();
    let out = map.transform(&pts, true).map_err(|_| ())?;
    Ok(Some([out.point(0)[0], out.point(1)[0]]))
}

fn run(name: &str) -> Result<Option<[f64; 2]>, ()> {
    let mut parts = name.split(':');
    let grid = parts.next().unwrap();
    let from = parts.next().unwrap();
    let to = parts.next().unwrap();
    if grid == "y" {
        return convert(&system_frame(from), &system_frame(to), [0.25, 1.75]);
    }
    let c: usize = grid[1..].parse().unwrap();
    convert(
        &scale_frame(c, from, false),
        &scale_frame(c, to, true),
        cases::POINTS,
    )
}

#[test]
fn convert_matches_the_c_library() {
    let failures: Vec<String> = cases::CASES
        .iter()
        .filter(|(name, _)| !excluded(name))
        .filter_map(|&(name, want)| {
            let got = run(name);
            (got != want).then(|| format!("{name}: got {got:?}, C gives {want:?}"))
        })
        .collect();
    assert!(
        failures.is_empty(),
        "{} of {} cases differ from C:\n{}",
        failures.len(),
        cases::CASES.len(),
        failures.join("\n")
    );
}

/// Each excluded case still differs from C; one that matches must be
/// removed from .
#[test]
fn excluded_cases_still_differ() {
    for &(name, reason) in TIMEMAP_EXCLUDED {
        let want = cases::CASES
            .iter()
            .find(|c| c.0 == name)
            .map(|c| c.1)
            .expect("excluded case is in the corpus");
        assert_ne!(
            run(name),
            want,
            "{name} now matches C; remove it from TIMEMAP_EXCLUDED ({reason})"
        );
    }
}
